String // ID Discord du membre\n  username    String // pseudo au moment de l'ajout, pour l'affichage\n  avatar      String? // hash de son avatar Discord\n  modules     DashboardModule[]\n  grantedById String // l'admin qui a donné l'accès\n  createdAt   DateTime          @default(now())\n  updatedAt   DateTime          @updatedAt\n\n  @@id([guildId, userId])\n  @@index([userId])\n}\n\n// ---------- Modération ----------\nenum CaseType {\n  WARN\n  MUTE\n  UNMUTE\n  KICK\n  BAN\n  UNBAN\n}\n\n// d'où vient la levée d'une sanction ; null : levée avant ce suivi\nenum RevocationSource {\n  COMMAND // une commande du bot\n  SCHEDULE // la levée automatique d'un ban temporaire\n  DASHBOARD // le tableau de bord\n}\n\nmodel Case {\n  id          Int               @id @default(autoincrement())\n  guildId     String\n  guild       Guild             @relation(fields: [guildId], references: [id], onDelete: Cascade)\n  number      Int // #1, #2… propre à la guilde\n  type        CaseType\n  targetId    String\n  moderatorId String\n  reason      String?\n  expiresAt   DateTime? // mute ou ban temporaire\n  revokedAt   DateTime? // clearwarn, unban, unmute\n  revokedById String?\n  revokedVia  RevocationSource?\n  createdAt   DateTime          @default(now())\n\n  @@unique([guildId, number])\n  @@index([guildId, targetId])\n  @@index([guildId, moderatorId]) // filtre « modérateur » de l'onglet Modération\n  @@index([guildId, createdAt]) // filtre par période\n  @@index([type, expiresAt]) // bans temporaires à lever\n}\n\n// ---------- XP et fun ----------\nmodel MemberLevel {\n  guildId     String\n  userId      String\n  guild       Guild     @relation(fields: [guildId], references: [id], onDelete: Cascade)\n  xp          Int       @default(0)\n  level       Int       @default(0)\n  messages    Int       @default(0) // messages qui ont rapporté de l'XP\n  lastXpAt    DateTime?\n  // copiés à chaque gain : le classement public s'affiche sans appeler Discord\n  displayName String?\n  avatarUrl   String?\n\n  @@id([guildId, userId])\n  @@index([guildId, xp(sort: Desc)])\n}\n\n// un seul mariage par membre et par serveur : vérifié dans le service\nmodel Marriage {\n  id        Int      @id @default(autoincrement())\n  guildId   String\n  guild     Guild    @relation(fields: [guildId], references: [id], onDelete: Cascade)\n  user1Id   String // paire triée : user1Id < user2Id\n  user2Id   String\n  createdAt DateTime @default(now())\n\n  @@unique([guildId, user1Id, user2Id])\n  @@index([guildId, user2Id])\n}\n\n// ---------- Tickets ----------\nenum TicketStatus {\n  OPEN\n  CLOSED\n}\n\n/**\n * Comment un ticket a été fermé : le bouton, la fermeture automatique, ou la suppression du salon.\n */\nenum TicketCloseSource {\n  BUTTON\n  INACTIVITY\n  CHANNEL_DELETED\n}\n\nmodel Ticket {\n  id                   Int                @id @default(autoincrement())\n  guildId              String\n  guild                Guild              @relation(fields: [guildId], references: [id], onDelete: Cascade)\n  number               Int\n  channelId            String             @unique\n  ownerId              String\n  ownerName            String? // pseudo à l'ouverture, pour la liste du site\n  status               TicketStatus       @default(OPEN)\n  closedById           String?\n  closedByName         String?\n  messageCount         Int? // messages dans le transcript\n  transcriptKey        String? // clé S3 du transcript\n  createdAt            DateTime           @default(now())\n  closedAt             DateTime?\n  claimedById          String? // qui a pris le ticket en charge (null : personne)\n  claimedByName        String? // pseudo à la prise en charge, pour la liste du site\n  claimedAt            DateTime?\n  rating               Int? // note de 1 à 5 donnée par l'auteur après fermeture (CHECK en base) ; jamais exposée seule\n  ratedAt              DateTime?\n  typeId               Int? // type choisi à l'ouverture ; null si le type a été supprimé (ticket ancien ou type effacé)\n  type                 TicketType?        @relation(fields: [typeId], references: [id], onDelete: SetNull)\n  lastActivityAt       DateTime           @default(now()) // dernier message d'un membre dans le salon ; point de départ du délai d'inactivité\n  inactivityRemindedAt DateTime? // rappel d'inactivité envoyé (effacé par la moindre activité) ; null : pas de rappel en cours\n  closedVia            TicketCloseSource? // null : ticket ouvert, ou fermé avant ce suivi\n  inactivityFailedAt   DateTime? // dernier échec de la fermeture automatique (Discord, Garage…) : nouvel essai 1 h plus tard\n\n  @@unique([guildId, number])\n  @@index([guildId, status])\n  @@index([guildId, ownerId, status])\n  @@index([guildId, typeId])\n  @@index([status, lastActivityAt])\n}\n\nenum TicketTypeQuestionStyle {\n  SHORT\n  PARAGRAPH\n}\n\n/**\n * Un type de ticket d'un serveur : sa catégorie Discord, les rôles qui voient ses salons et son\n * formulaire d'ouverture. Les réponses au formulaire ne sont JAMAIS stockées : le bot les poste\n * dans le salon du ticket (voir ADR-0011).\n */\nmodel TicketType {\n  id              Int                  @id @default(autoincrement())\n  guildId         String\n  guild           Guild                @relation(fields: [guildId], references: [id], onDelete: Cascade)\n  name            String // 80 caractères au plus (validé par @phenix/shared)\n  description     String? // 100 caractères au plus : le menu de choix du panel\n  emoji           String?\n  categoryId      String // catégorie Discord où le bot range les salons de ce type\n  staffRoleIds    String[]\n  inactivityHours Int? // heures sans message avant la fermeture automatique (choix de TICKET_INACTIVITY_CHOICES) ; null : jamais\n  position        Int                  @default(0)\n  questions       TicketTypeQuestion[]\n  tickets         Ticket[]\n  createdAt       DateTime             @default(now())\n  updatedAt       DateTime             @updatedAt\n\n  @@index([guildId, position])\n}\n\n/**\n * Une question du formulaire d'un type (0 à 5, dans l'ordre de position).\n */\nmodel TicketTypeQuestion {\n  id          Int                     @id @default(autoincrement())\n  typeId      Int\n  type        TicketType              @relation(fields: [typeId], references: [id], onDelete: Cascade)\n  label       String // 45 caractères au plus\n  placeholder String? // 100 caractères au plus\n  style       TicketTypeQuestionStyle @default(SHORT)\n  required    Boolean                 @default(true)\n  maxLength   Int                     @default(1000) // 1000 au plus (limite de Discord)\n  position    Int                     @default(0)\n\n  @@index([typeId, position])\n}\n\n/**\n * Le message « Ouvrir un ticket » d'un serveur : un seul par serveur.\n */\nmodel TicketPanel {\n  guildId      String    @id\n  guild        Guild     @relation(fields: [guildId], references: [id], onDelete: Cascade)\n  channelId    String\n  messageId    String?   @unique\n  title        String\n  description  String?\n  buttonLabel  String\n  // publication : mêmes règles que RolePanel\n  publishedAt  DateTime?\n  publishError String?\n}\n\n// ---------- Giveaways ----------\nmodel Giveaway {\n  id             Int             @id @default(autoincrement())\n  guildId        String\n  guild          Guild           @relation(fields: [guildId], references: [id], onDelete: Cascade)\n  channelId      String\n  messageId      String?         @unique // vide tant que le bot n'a pas posté\n  hostId         String\n  prize          String\n  winnersCount   Int             @default(1)\n  requiredRoleId String?\n  endsAt         DateTime\n  endedAt        DateTime? // tirage fait : les gagnants sont dans winnerIds\n  winnerIds      String[]\n  announcedAt    DateTime? // message final et félicitations envoyés\n  // publication du message : mêmes règles que les panels\n  publishedAt    DateTime?\n  publishError   String?\n  entries        GiveawayEntry[]\n  createdAt      DateTime        @default(now())\n\n  @@index([guildId, endedAt])\n}\n\nmodel GiveawayEntry {\n  giveawayId  Int\n  userId      String\n  displayName String? // pseudo à l'inscription, pour afficher les gagnants sur le site\n  giveaway    Giveaway @relation(fields: [giveawayId], references: [id], onDelete: Cascade)\n  createdAt   DateTime @default(now())\n\n  @@id([giveawayId, userId])\n}\n\n// ---------- Autorole (panels de boutons) ----------\nenum RolePanelMode {\n  MULTIPLE // plusieurs rôles possibles\n  UNIQUE // un seul rôle à la fois\n}\n\nmodel RolePanel {\n  id           Int               @id @default(autoincrement())\n  guildId      String\n  guild        Guild             @relation(fields: [guildId], references: [id], onDelete: Cascade)\n  channelId    String\n  messageId    String?           @unique\n  title        String\n  description  String?\n  mode         RolePanelMode     @default(MULTIPLE)\n  options      RolePanelOption[]\n  // publication : le site remet les deux à null, le bot remplit l'un ou l'autre\n  publishedAt  DateTime?\n  publishError String?\n  createdAt    DateTime          @default(now())\n\n  @@index([guildId])\n}\n\nmodel RolePanelOption {\n  id       Int       @id @default(autoincrement())\n  panelId  Int\n  panel    RolePanel @relation(fields: [panelId], references: [id], onDelete: Cascade)\n  roleId   String\n  label    String\n  emoji    String?\n  position Int       @default(0)\n}\n\n// ---------- The Division 2 ----------\n// mêmes plateformes que l'API tracker.gg (ubi, psn, xbl)\nenum Td2Platform {\n  UBI\n  PSN\n  XBL\n}\n\nenum Td2ActivityKind {\n  RAID\n  INCURSION\n}\n\nenum Td2Role {\n  DPS\n  HEAL\n  TANK\n  HEAL_TANK // build hybride des incursions\n  PLAYER // missions : une place, sans rôle\n}\n\n// difficulté d'une mission, comme dans le jeu\nenum Td2Difficulty {\n  NORMAL\n  HARD\n  CHALLENGING\n  HEROIC\n  LEGENDARY\n}\n\nenum Td2SignupStatus {\n  CONFIRMED\n  RESERVE // rôle complet : en attente d'une place\n}\n\nenum Td2ReportStatus {\n  PENDING // affiché « non vérifié » hors du serveur d'origine\n  IN_REVIEW\n  CONFIRMED\n  REJECTED // jamais visible hors du serveur d'origine\n}\n\n// profil lié par /td2 link, commun à tous les serveurs\nmodel Td2Profile {\n  userId     String      @id // ID Discord\n  platform   Td2Platform\n  playerName String\n  linkedAt   DateTime    @default(now())\n}\n\n// catalogue global, géré par le propriétaire du bot : Dark Hours, Paradis Perdu…\nmodel Td2Activity {\n  id     Int               @id @default(autoincrement())\n  kind   Td2ActivityKind\n  name   String\n  active Boolean           @default(true)\n  modes  Td2ActivityMode[]\n\n  @@unique([kind, name])\n}\n\n// un mode = une composition : Normal, Semi-Speed…\nmodel Td2ActivityMode {\n  id         Int           @id @default(autoincrement())\n  activityId Int\n  activity   Td2Activity   @relation(fields: [activityId], references: [id], onDelete: Cascade)\n  name       String\n  slots      Td2ModeSlot[]\n  events     Td2Event[]\n\n  @@unique([activityId, name])\n}\n\n// nombre de places par rôle pour un mode\nmodel Td2ModeSlot {\n  modeId Int\n  role   Td2Role\n  count  Int\n  mode   Td2ActivityMode @relation(fields: [modeId], references: [id], onDelete: Cascade)\n\n  @@id([modeId, role])\n}\n\n// directives : les règles qui durcissent une mission, gérées par le propriétaire du bot\nmodel Td2Directive {\n  id          Int     @id @default(autoincrement())\n  name        String  @unique\n  description String?\n  active      Boolean @default(true)\n}\n\nmodel Td2Event {\n  id          Int              @id @default(autoincrement())\n  guildId     String\n  guild       Guild            @relation(fields: [guildId], references: [id], onDelete: Cascade)\n  // null pour une mission ; Restrict : supprimer un mode ne change pas un raid en mission\n  modeId      Int?\n  mode        Td2ActivityMode? @relation(fields: [modeId], references: [id], onDelete: Restrict)\n  missionName String? // mission : le nom choisi par l'organisateur\n  difficulty  Td2Difficulty? // mission : sa difficulté\n  directives  String[]         @default([]) // mission : noms des directives, copiés à la création\n  scheduledAt DateTime\n  channelId   String\n  messageId   String?          @unique\n  organizerId String\n  cancelledAt DateTime?\n  slots       Td2EventSlot[] // composition copiée du mode à la création\n  signups     Td2Signup[]\n  createdAt   DateTime         @default(now())\n}\n\nmodel Td2EventSlot {\n  eventId Int\n  role    Td2Role\n  count   Int\n  event   Td2Event @relation(fields: [eventId], references: [id], onDelete: Cascade)\n\n  @@id([eventId, role])\n}\n\nmodel Td2Signup {\n  eventId   Int\n  userId    String\n  role      Td2Role\n  status    Td2SignupStatus @default(CONFIRMED)\n  event     Td2Event        @relation(fields: [eventId], references: [id], onDelete: Cascade)\n  createdAt DateTime        @default(now()) // ordre de passage de la réserve\n\n  @@id([eventId, userId])\n}\n\n// signalement partagé entre tous les serveurs du bot\nmodel Td2Report {\n  id              Int             @id @default(autoincrement())\n  guildId         String // serveur d'origine\n  guild           Guild           @relation(fields: [guildId], references: [id], onDelete: Cascade)\n  reporterId      String // visible du seul staff d'origine\n  playerName      String // pseudo tel que saisi\n  playerNameLower String // pour les recherches\n  platform        Td2Platform\n  reason          String\n  details         String?\n  evidenceKeys    String[] // clés S3 des preuves, au moins une pour confirmer\n  status          Td2ReportStatus @default(PENDING)\n  reviewedById    String?\n  reviewedAt      DateTime?\n  staffMessageId  String?         @unique // embed dans le salon staff d'origine\n  createdAt       DateTime        @default(now())\n\n  @@index([platform, playerNameLower])\n  @@index([guildId, status])\n}\n\n// ---------- Forum (unique, pour tout le site) ----------\nmodel ForumCategory {\n  id          Int           @id @default(autoincrement())\n  slug        String        @unique\n  name        String\n  description String?\n  position    Int           @default(0)\n  threads     ForumThread[]\n}\n\nmodel ForumThread {\n  id         Int           @id @default(autoincrement())\n  categoryId Int\n  category   ForumCategory @relation(fields: [categoryId], references: [id], onDelete: Cascade)\n  authorId   String\n  author     User          @relation(fields: [authorId], references: [id])\n  title      String\n  pinned     Boolean       @default(false)\n  locked     Boolean       @default(false)\n  posts      ForumPost[]\n  createdAt  DateTime      @default(now())\n  updatedAt  DateTime      @updatedAt // dernière activité : une réponse le fait avancer\n\n  // La liste d'une catégorie : épinglés d'abord, puis du plus récent au plus ancien\n  @@index([categoryId, pinned, updatedAt])\n}\n\n// image du forum, ré-encodée en WebP et rangée dans le bucket media\nmodel ForumAttachment {\n  id         String     @id @default(uuid())\n  postId     Int? // vide tant que le message n'est pas publié\n  post       ForumPost? @relation(fields: [postId], references: [id], onDelete: Cascade)\n  uploaderId String\n  uploader   User       @relation(fields: [uploaderId], references: [id])\n  key        String     @unique // clé dans le bucket media\n  sizeBytes  Int\n  width      Int\n  height     Int\n  createdAt  DateTime   @default(now())\n\n  @@index([postId])\n}\n\nmodel ForumPost {\n  id          Int               @id @default(autoincrement())\n  threadId    Int\n  thread      ForumThread       @relation(fields: [threadId], references: [id], onDelete: Cascade)\n  authorId    String\n  author      User              @relation(fields: [authorId], references: [id])\n  content     String\n  attachments ForumAttachment[]\n  editedAt    DateTime?\n  createdAt   DateTime          @default(now())\n\n  // Les messages d'un sujet, dans l'ordre\n  @@index([threadId, createdAt])\n}\n\n// ---------- Métriques des propriétaires du bot (phase 11) ----------\n\n/// L'utilisation des commandes, heure par heure : la commande et le serveur, jamais le membre.\nmodel CommandUsage {\n  hour            DateTime // début de l'heure, en UTC\n  /// '' : hors serveur (message privé). Pas de clé étrangère : un serveur quitté garde son historique\n  guildId         String\n  /// Avec la sous-commande : « td2 mission »\n  command         String\n  count           Int      @default(0)\n  errors          Int      @default(0)\n  totalDurationMs Int      @default(0)\n\n  @@id([hour, guildId, command])\n  @@index([hour])\n}\n\n/// Un relevé (CPU, RAM, stockage) toutes les 5 minutes, effacé après 30 jours.\nmodel MetricSample {\n  /// bot.cpu, api.memory, postgres.bytes, garage.media.objects…\n  name    String\n  /// Aligné sur le créneau de 5 minutes : deux écritures du même créneau n'en font qu'une\n  takenAt DateTime\n  value   Float\n\n  @@id([name, takenAt])\n  @@index([takenAt])\n}\n",
